"""The labelled evaluation dataset.

Three classes of data, and the third one is the point.

**Benign** — ordinary estate activity: users logging in from their usual
addresses during their usual hours, routine process execution, backup jobs,
cloud API calls from CI. Establishes the baseline and provides the denominator
for precision.

**Malicious** — the attack scenarios, generated by the same simulators the
platform ships. Provides the denominator for recall.

**Ambiguous** — benign activity that legitimately resembles an attack: an
administrator running the same enumeration commands an intruder would, a backup
account authenticating to the whole estate at 02:00, configuration management
writing a cron entry, a user who mistyped their password four times and then
succeeded.

Ambiguous cases are excluded from precision and recall — scoring them either way
would be a claim about ground truth that nobody can justify — and reported
separately as false-positive *pressure*. Any evaluation that omits this class
reports a precision figure that will not survive contact with production, and a
platform that claims 99% precision against benign-versus-attack data is not
measuring the thing that matters.
"""

from __future__ import annotations

import datetime as dt
import random
import zlib
from dataclasses import dataclass, field
from typing import Any

from app.models.enums import GroundTruthLabel
from app.simulators.base import (
    TelemetryRecord,
    cloud_audit,
    edr_process,
    file_event,
    jitter,
    linux_auth,
    network_flow,
)
from app.simulators.environment import DEFAULT_ENVIRONMENT, Environment
from app.simulators.registry import get_simulator


@dataclass(slots=True)
class LabelledDataset:
    name: str
    seed: int
    records: list[TelemetryRecord] = field(default_factory=list)
    #: Ground truth for scenario-level scoring: scenario key -> window and the
    #: rules that should have fired.
    scenario_windows: dict[str, dict[str, Any]] = field(default_factory=dict)
    start: dt.datetime | None = None
    end: dt.datetime | None = None

    def counts(self) -> dict[str, int]:
        result = {"benign": 0, "malicious": 0, "ambiguous": 0, "unlabelled": 0}
        for record in self.records:
            key = record.label or "unlabelled"
            result[key] = result.get(key, 0) + 1
        return result

    def composition(self) -> dict[str, Any]:
        return {
            "name": self.name,
            "seed": self.seed,
            "total_records": len(self.records),
            "counts": self.counts(),
            "scenarios": sorted(self.scenario_windows.keys()),
            "start": self.start.isoformat() if self.start else None,
            "end": self.end.isoformat() if self.end else None,
        }


# --------------------------------------------------------------------------
# Benign background
# --------------------------------------------------------------------------
BENIGN_COMMANDS = [
    ("/usr/bin/git", "git pull --rebase"),
    ("/usr/bin/python3", "python3 manage.py migrate"),
    ("/usr/bin/docker", "docker compose up -d"),
    ("/usr/bin/tail", "tail -f /var/log/app/service.log"),
    ("/usr/bin/systemctl", "systemctl status app.service"),
    ("/usr/bin/vim", "vim /srv/app/config.yaml"),
    ("/usr/bin/pytest", "pytest tests/ -q"),
    ("/usr/bin/npm", "npm run build"),
]

BENIGN_CLOUD_CALLS = [
    ("GetCallerIdentity", "sts.amazonaws.com"),
    ("ListBuckets", "s3.amazonaws.com"),
    ("DescribeInstances", "ec2.amazonaws.com"),
    ("GetObject", "s3.amazonaws.com"),
    ("PutObject", "s3.amazonaws.com"),
]


def _benign_day(
    env: Environment,
    rng: random.Random,
    day_start: dt.datetime,
) -> list[TelemetryRecord]:
    """One day of ordinary activity across the estate."""
    records: list[TelemetryRecord] = []

    for user in env.users:
        if user.user_type == "cloud":
            continue
        start_hour, end_hour = user.active_hours
        sessions = rng.randint(1, 3) if user.user_type == "human" else rng.randint(2, 4)

        for _ in range(sessions):
            hour = rng.randint(start_hour, max(start_hour, end_hour - 1))
            moment = day_start.replace(hour=hour % 24, minute=rng.randint(0, 59), second=rng.randint(0, 59))
            host = rng.choice(user.home_hosts) if user.home_hosts else "LINUX-03"
            source_ip = rng.choice(user.home_ips) if user.home_ips else "10.20.9.10"

            records.append(linux_auth(
                moment, host, "sshd",
                f"Accepted publickey for {user.user_id} from {source_ip} "
                f"port {rng.randint(40000, 60000)} ssh2: RSA SHA256:benignkeyfingerprint0001",
                pid=rng.randint(2000, 6000),
                label=GroundTruthLabel.BENIGN, scenario="benign_auth",
            ))
            moment += dt.timedelta(seconds=jitter(rng, 3))
            records.append(linux_auth(
                moment, host, "sshd",
                f"pam_unix(sshd:session): session opened for user {user.user_id}(uid=1000) by (uid=0)",
                label=GroundTruthLabel.BENIGN, scenario="benign_auth",
            ))

            for _ in range(rng.randint(2, 6)):
                moment += dt.timedelta(seconds=jitter(rng, rng.randint(60, 900)))
                executable, command = rng.choice(BENIGN_COMMANDS)
                records.append(edr_process(
                    moment, host, user.user_id, executable, command,
                    pid=rng.randint(10000, 40000), parent="bash",
                    label=GroundTruthLabel.BENIGN, scenario="benign_process",
                ))

            for _ in range(rng.randint(1, 3)):
                moment += dt.timedelta(seconds=jitter(rng, rng.randint(60, 600)))
                records.append(network_flow(
                    moment, host, env.host_ip(host), f"10.20.7.{rng.randint(10, 60)}",
                    rng.choice([443, 5432, 6379, 8080]),
                    user_id=user.user_id, bytes_out=rng.randint(500, 40000),
                    bytes_in=rng.randint(500, 90000), process="app",
                    label=GroundTruthLabel.BENIGN, scenario="benign_network",
                ))

    # A handful of genuine authentication failures: people mistype passwords, and
    # a dataset with zero failures would make the threshold rules look better
    # than they are.
    for _ in range(rng.randint(3, 8)):
        user = rng.choice([u for u in env.users if u.user_type == "human"])
        host = rng.choice(user.home_hosts) if user.home_hosts else "LINUX-03"
        source_ip = rng.choice(user.home_ips) if user.home_ips else "10.20.9.10"
        moment = day_start.replace(hour=rng.randint(8, 18), minute=rng.randint(0, 59))
        records.append(linux_auth(
            moment, host, "sshd",
            f"Failed password for {user.user_id} from {source_ip} port {rng.randint(40000, 60000)} ssh2",
            label=GroundTruthLabel.BENIGN, scenario="benign_auth_failure",
        ))

    # Cloud identities: routine, read-heavy, from their usual address.
    for user in env.users:
        if user.user_type != "cloud":
            continue
        source_ip = user.home_ips[0] if user.home_ips else "198.51.100.10"
        for _ in range(rng.randint(6, 14)):
            hour = rng.randint(user.active_hours[0], max(user.active_hours[0], user.active_hours[1] - 1))
            moment = day_start.replace(hour=hour % 24, minute=rng.randint(0, 59))
            api, service = rng.choice(BENIGN_CLOUD_CALLS)
            records.append(cloud_audit(
                moment, api, user.user_id, account=env.cloud_account, source_ip=source_ip,
                region=env.cloud_region, service=service, read_only=True, mfa=True,
                label=GroundTruthLabel.BENIGN, scenario="benign_cloud",
            ))

    return records


# --------------------------------------------------------------------------
# Ambiguous cases
# --------------------------------------------------------------------------
def _ambiguous_cases(
    env: Environment,
    rng: random.Random,
    base: dt.datetime,
) -> list[TelemetryRecord]:
    """Benign activity shaped like an attack.

    Each case is chosen because it satisfies a real rule's condition. They are
    the cases a deployed platform actually argues about.
    """
    records: list[TelemetryRecord] = []

    # 1. An administrator triaging a host runs the same commands an intruder does.
    moment = base.replace(hour=11, minute=14)
    for executable, command in [
        ("/usr/bin/whoami", "whoami"), ("/usr/bin/id", "id"),
        ("/usr/bin/uname", "uname -a"), ("/usr/bin/netstat", "netstat -antp"),
        ("/usr/bin/last", "last -n 40"), ("/usr/bin/sudo", "sudo -l"),
    ]:
        records.append(edr_process(
            moment, "LINUX-07", "admin", executable, command,
            pid=rng.randint(20000, 30000), parent="bash",
            label=GroundTruthLabel.AMBIGUOUS, scenario="ambiguous_admin_triage",
        ))
        moment += dt.timedelta(seconds=jitter(rng, 11))

    # 2. The backup service touches the whole estate at 02:00, every night.
    moment = base.replace(hour=2, minute=3)
    for host in ["LINUX-03", "LINUX-07", "LINUX-11", "LINUX-DB-02", "LINUX-21"]:
        records.append(linux_auth(
            moment, host, "sshd",
            f"Accepted publickey for svc-backup from 10.20.4.77 port {rng.randint(40000, 60000)} ssh2: "
            "RSA SHA256:backupserviceaccountkey00001",
            label=GroundTruthLabel.AMBIGUOUS, scenario="ambiguous_backup_sweep",
        ))
        moment += dt.timedelta(seconds=jitter(rng, 45))

    # 3. Configuration management writes a cron entry on every convergence run.
    moment = base.replace(hour=4, minute=30)
    for host in ["LINUX-03", "LINUX-07"]:
        records.append(file_event(
            moment, host, "root", "/etc/cron.d/ansible-managed-backup", "modify",
            mode="0644", sha256="e" * 64, process="ansible-playbook",
            label=GroundTruthLabel.AMBIGUOUS, scenario="ambiguous_config_management",
        ))
        moment += dt.timedelta(seconds=jitter(rng, 20))

    # 4. A user mistypes their password four times, then gets it right.
    moment = base.replace(hour=9, minute=2)
    for _ in range(4):
        records.append(linux_auth(
            moment, "LINUX-21", "sshd",
            f"Failed password for bob from 10.20.9.34 port {rng.randint(40000, 60000)} ssh2",
            label=GroundTruthLabel.AMBIGUOUS, scenario="ambiguous_password_typo",
        ))
        moment += dt.timedelta(seconds=jitter(rng, 14))
    records.append(linux_auth(
        moment, "LINUX-21", "sshd",
        f"Accepted password for bob from 10.20.9.34 port {rng.randint(40000, 60000)} ssh2",
        label=GroundTruthLabel.AMBIGUOUS, scenario="ambiguous_password_typo",
    ))

    # 5. A CI pipeline enumerates cloud inventory before deploying.
    moment = base.replace(hour=13, minute=47)
    for api, service in [
        ("GetCallerIdentity", "sts.amazonaws.com"), ("ListRoles", "iam.amazonaws.com"),
        ("ListUsers", "iam.amazonaws.com"), ("ListBuckets", "s3.amazonaws.com"),
        ("DescribeInstances", "ec2.amazonaws.com"), ("ListAccessKeys", "iam.amazonaws.com"),
    ]:
        records.append(cloud_audit(
            moment, api, "ci-deployer", account=env.cloud_account,
            source_ip="198.51.100.5", region=env.cloud_region, service=service,
            read_only=True, mfa=True,
            label=GroundTruthLabel.AMBIGUOUS, scenario="ambiguous_ci_enumeration",
        ))
        moment += dt.timedelta(seconds=jitter(rng, 9))

    # 6. An engineer legitimately elevates after checking their rights.
    moment = base.replace(hour=15, minute=22)
    records.append(edr_process(
        moment, "LINUX-21", "alice", "/usr/bin/sudo", "sudo -l",
        pid=rng.randint(20000, 30000), parent="bash",
        label=GroundTruthLabel.AMBIGUOUS, scenario="ambiguous_legitimate_sudo",
    ))
    moment += dt.timedelta(seconds=jitter(rng, 25))
    records.append(linux_auth(
        moment, "LINUX-21", "sudo",
        "  alice : TTY=pts/0 ; PWD=/srv/app ; USER=root ; COMMAND=/usr/bin/systemctl restart app",
        label=GroundTruthLabel.AMBIGUOUS, scenario="ambiguous_legitimate_sudo",
    ))

    return records


# --------------------------------------------------------------------------
# Dataset assembly
# --------------------------------------------------------------------------
DEFAULT_SCENARIOS = (
    "brute_force",
    "password_spraying",
    "credential_abuse",
    "account_discovery",
    "privilege_escalation",
    "persistence",
    "lateral_movement",
    "cloud_iam",
)

#: Per-scenario overrides for the evaluation dataset.
#:
#: The Windows variants are enabled here because the evaluation is what makes a
#: coverage gap visible: without Windows telemetry in the dataset, the two
#: Windows rules never fire, and "never fired" is indistinguishable from "works"
#: in any metric that only counts what did happen. The harness reports silent
#: rules for exactly this reason.
SCENARIO_PARAMS: dict[str, dict[str, Any]] = {
    "privilege_escalation": {"include_windows": True},
    "persistence": {"include_windows": True},
}


def build_dataset(
    *,
    seed: int = 1337,
    benign_days: int = 5,
    scenarios: tuple[str, ...] = DEFAULT_SCENARIOS,
    include_ambiguous: bool = True,
    env: Environment | None = None,
    name: str = "sentinel-x-eval-v1",
) -> LabelledDataset:
    """Assemble a reproducible labelled dataset.

    Deterministic given ``seed``: the same seed yields byte-identical telemetry,
    so two evaluation runs are comparable and a reported metric can be
    reproduced by anyone with the repository.
    """
    env = env or DEFAULT_ENVIRONMENT
    rng = random.Random(seed)
    dataset = LabelledDataset(name=name, seed=seed)

    # Anchored to a fixed date so results do not drift with the wall clock.
    end = dt.datetime(2026, 3, 2, 0, 0, 0, tzinfo=dt.UTC)
    start = end - dt.timedelta(days=benign_days)

    for day in range(benign_days):
        day_start = start + dt.timedelta(days=day)
        dataset.records.extend(_benign_day(env, rng, day_start))

    if include_ambiguous:
        dataset.records.extend(_ambiguous_cases(env, rng, start + dt.timedelta(days=benign_days - 1)))

    # Attacks are placed on the final day, spaced so that separate scenarios do
    # not accidentally correlate into one another.
    attack_day = start + dt.timedelta(days=benign_days - 1)
    slot = attack_day.replace(hour=5, minute=0, second=0, microsecond=0)

    for scenario_key in scenarios:
        simulator = get_simulator(scenario_key)
        if simulator is None:
            continue
        params = {**simulator.spec.default_params, **SCENARIO_PARAMS.get(scenario_key, {})}
        produced = simulator.generate(env, random.Random(_scenario_seed(seed, scenario_key)),
                                      slot, params)
        dataset.records.extend(produced)

        times = [_record_time(r) for r in produced]
        times = [t for t in times if t is not None]
        dataset.scenario_windows[scenario_key] = {
            "scenario": scenario_key,
            "name": simulator.spec.name,
            "start": min(times).isoformat() if times else None,
            "end": max(times).isoformat() if times else None,
            "record_count": len(produced),
            "expected_rules": list(simulator.spec.expected_detections),
            "expected_techniques": list(simulator.spec.techniques),
        }
        # Separation greater than the correlation window, so each scenario is
        # scored on its own merits rather than benefiting from its neighbours.
        slot = (max(times) if times else slot) + dt.timedelta(minutes=45)

    dataset.records.sort(key=lambda r: _record_time(r) or start)
    dataset.start = start
    dataset.end = max([t for t in (_record_time(r) for r in dataset.records) if t] + [end])
    return dataset


def _scenario_seed(seed: int, scenario_key: str) -> int:
    """A per-scenario RNG seed that is stable across processes.

    Not ``hash(scenario_key)``: Python randomises string hashing per process
    unless PYTHONHASHSEED is pinned, so the builtin produced a different seed on
    every run. The confusion matrix was robust to it, but the generated
    telemetry genuinely differed between runs and the measured detection latency
    moved by tens of seconds — which quietly falsified this project's claim that
    a seeded evaluation is reproducible.

    CRC32 is not a security primitive and is not being used as one. It is used
    here because it is stable, cheap and deterministic across interpreters.
    """
    return seed + zlib.crc32(scenario_key.encode("utf-8")) % 10_000


def _record_time(record: TelemetryRecord) -> dt.datetime | None:
    from app.core.timeutils import parse_timestamp

    for key in ("timestamp", "@timestamp", "start_time", "time", "TimeCreated", "eventTime"):
        value = record.record.get(key)
        if value:
            try:
                return parse_timestamp(value)
            except (ValueError, TypeError):
                continue
    return None
